package com.library.circulation;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import com.library.dto.BorrowRequest;
import com.library.entity.BorrowRecord;
import com.library.service.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.dao.DataAccessException;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.library.circulation.CirculationSupport.*;

@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:circulation_service;DB_CLOSE_DELAY=-1;MODE=MYSQL")
@ActiveProfiles("test")
public class CirculationServiceTest {
    @Autowired CirculationService service;
    @Autowired JdbcTemplate jdbc;
    @Autowired BorrowRecordService legacy;
    @Autowired PlatformTransactionManager tm;
    protected long admin,clerk,member;
    record Copy(long book,long copy,String barcode){}
    @BeforeEach void fixtures(){service.clock=Clock.fixed(Instant.parse("2026-10-20T02:00:00Z"),ZoneOffset.UTC);admin=user("ADMIN");clerk=user("LIBRARIAN");member=user("READER");}
    @AfterEach void resetClock(){service.clock=Clock.systemUTC();}
    long user(String role){String n=UUID.randomUUID().toString();jdbc.update("INSERT INTO sys_user(username,password,real_name,role,status) VALUES (?,'synthetic-only','合成借还会员',?,1)",n,role);return jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?",Long.class,n);}
    Copy copy(){String isbn=UUID.randomUUID().toString().replace("-","").substring(0,20),barcode="000Aa "+UUID.randomUUID();jdbc.update("INSERT INTO book(isbn,title,stock_total,stock_available,status) VALUES (?,'合成借还图书',1,1,1)",isbn);long b=jdbc.queryForObject("SELECT id FROM book WHERE isbn=?",Long.class,isbn);jdbc.update("INSERT INTO book_copy(book_id,barcode,status,location) VALUES (?,?,'AVAILABLE',NULL)",b,barcode);return new Copy(b,jdbc.queryForObject("SELECT id FROM book_copy WHERE book_id=?",Long.class,b),barcode);}
    ObjectNode borrow(Copy... copies){ArrayNode items=JSON.createArrayNode();for(Copy c:copies)items.add(obj("bookId",c.book,"copyId",c.copy,"borrowDays",30));return obj("operation","BORROW","userId",member,"items",items,"remark","");}
    ObjectNode returns(long... records){return obj("operation","RETURN","recordIds",records,"remark","");}
    JsonNode preview(String key,JsonNode input){return service.preview(key,input,admin);}
    JsonNode confirm(String key,JsonNode preview){return service.confirm(key,obj("previewDigest",preview.path("previewDigest")),admin);}
    JsonNode lend(Copy... copies){String k=UUID.randomUUID().toString();return confirm(k,preview(k,borrow(copies)));}
    int available(Copy c){return jdbc.queryForObject("SELECT stock_available FROM book WHERE id=?",Integer.class,c.book);}
    long count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
    void reason(String code,org.junit.jupiter.api.function.Executable action){Failure e=assertThrows(Failure.class,action);assertEquals(code,e.reason);}

    @Test void batchHasExplicitCopiesAndOneReceiptAndLiveOrderTracksPartialLegacyReturnAndRenewal(){
        Copy a=copy(),b=copy();String key=UUID.randomUUID().toString();JsonNode p=preview(key,borrow(a,b));assertEquals(1,available(a));assertEquals(1,available(b));assertEquals(0,p.path("preview").path("activeCountBefore").asInt());
        JsonNode r=confirm(key,p);assertEquals(2,r.path("items").size());assertEquals(0,available(a));assertEquals(2,service.order(r.path("orderId").asLong(),clerk).path("activeCount").asInt());
        long first=r.path("items").get(0).path("recordId").asLong(),second=r.path("items").get(1).path("recordId").asLong();
        legacy.renew(first,7);assertEquals("2026-11-26",service.order(r.path("orderId").asLong(),admin).path("items").get(0).path("dueDate").asText());
        legacy.returnBook(first);assertEquals("PARTIALLY_RETURNED",service.order(r.path("orderId").asLong(),admin).path("state").asText());
        String ret=UUID.randomUUID().toString();JsonNode rr=confirm(ret,preview(ret,returns(second)));assertTrue(rr.path("orderId").isNull());assertEquals("RETURNED",service.order(r.path("orderId").asLong(),admin).path("state").asText());
        assertEquals(1,available(a));assertEquals(1,available(b));assertEquals(r,confirm(key,p));assertEquals(r,service.get(key,admin).get("receipt"));
        assertEquals(2,jdbc.queryForObject("SELECT action_version FROM book_copy WHERE id=?",Integer.class,b.copy));
    }
    @Test void unknownCancelTombstonePreventsLatePreviewAndCannotBeClaimedByAnotherActor(){String key=UUID.randomUUID().toString();JsonNode cancelled=service.cancel(key,obj(),admin);assertEquals("CANCELLED",cancelled.path("state").asText());assertTrue(cancelled.path("input").isNull());assertEquals(cancelled,service.cancel(key,obj(),admin));reason("REQUEST_CANCELLED",()->preview(key,borrow(copy())));reason("OWNER_REQUIRED",()->service.get(key,clerk));reason("OWNER_REQUIRED",()->service.cancel(key,obj(),clerk));}
    @Test void originalInputAndTerminalReceiptsAreFrozenAndCancelReturnsActualCommittedState(){Copy c=copy();String k=UUID.randomUUID().toString();ObjectNode in=borrow(c);JsonNode p=preview(k,in);assertEquals(p,preview(k,in));ObjectNode changed=in.deepCopy();changed.put("remark","other");reason("IDEMPOTENCY_KEY_REUSED",()->preview(k,changed));JsonNode r=confirm(k,p);assertEquals("COMMITTED",service.cancel(k,obj(),admin).path("state").asText());service.clock=Clock.fixed(Instant.parse("2026-10-22T02:00:00Z"),ZoneOffset.UTC);assertEquals(r,confirm(k,p));assertEquals(r,preview(k,in).path("receipt"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM stock_flow WHERE related_id=?",Integer.class,r.path("items").get(0).path("recordId").asLong()));}
    @Test void previewExpiryAndShanghaiMidnightAndCopyAbaRequireFreshReview(){Copy c=copy();String k=UUID.randomUUID().toString();JsonNode p=preview(k,borrow(c));service.clock=Clock.fixed(Instant.parse("2026-10-20T02:15:00Z"),ZoneOffset.UTC);reason("PREVIEW_EXPIRED",()->confirm(k,p));assertEquals(1,available(c));
        service.clock=Clock.fixed(Instant.parse("2026-10-20T15:59:00Z"),ZoneOffset.UTC);String mid=UUID.randomUUID().toString();JsonNode mp=preview(mid,borrow(c));service.clock=Clock.fixed(Instant.parse("2026-10-20T16:00:00Z"),ZoneOffset.UTC);reason("PREVIEW_EXPIRED",()->confirm(mid,mp));
        service.clock=Clock.fixed(Instant.parse("2026-10-20T02:00:00Z"),ZoneOffset.UTC);String aba=UUID.randomUUID().toString();JsonNode ap=preview(aba,borrow(c));BorrowRequest br=new BorrowRequest();br.setUserId(member);br.setBookId(c.book);br.setCopyId(c.copy);BorrowRecord record=legacy.borrow(br);legacy.returnBook(record.getId());reason("PREVIEW_STALE",()->confirm(aba,ap));assertEquals(1,available(c));}
    @Test void changedSecondItemMakesWholeBatchRollbackAndDoesNotReserveInventory(){Copy a=copy(),b=copy();String k=UUID.randomUUID().toString();JsonNode p=preview(k,borrow(a,b));long orders=count("circulation_order"),flows=count("stock_flow"),records=count("borrow_record");jdbc.update("UPDATE book_copy SET status='other',action_version=action_version+1 WHERE id=?",b.copy);reason("PREVIEW_STALE",()->confirm(k,p));assertEquals(orders,count("circulation_order"));assertEquals(flows,count("stock_flow"));assertEquals(records,count("borrow_record"));assertEquals(1,available(a));assertEquals("AVAILABLE",jdbc.queryForObject("SELECT status FROM book_copy WHERE id=?",String.class,a.copy));}
    protected void installReceiptFailure(){jdbc.execute("CREATE TRIGGER circulation_receipt_fail BEFORE UPDATE ON circulation_request FOR EACH ROW CALL 'com.library.circulation.CirculationServiceTest$ReceiptFailure'");}
    protected void removeReceiptFailure(){jdbc.execute("DROP TRIGGER circulation_receipt_fail");}
    public static class ReceiptFailure implements org.h2.api.Trigger {public void fire(Connection c,Object[] old,Object[] next)throws SQLException{if("COMMITTED".equals(next[3]))throw new SQLException("synthetic receipt failure","45000");}}
    @Test void finalReceiptFailureRollsBackEveryBusinessWriteAndOriginalRequestCanRetry(){Copy a=copy(),b=copy();String k=UUID.randomUUID().toString();JsonNode p=preview(k,borrow(a,b));long orders=count("circulation_order"),items=count("circulation_order_item"),flows=count("stock_flow"),records=count("borrow_record");installReceiptFailure();try{reason("CIRCULATION_SAVE_FAILED",()->confirm(k,p));}finally{removeReceiptFailure();}assertEquals(orders,count("circulation_order"));assertEquals(items,count("circulation_order_item"));assertEquals(flows,count("stock_flow"));assertEquals(records,count("borrow_record"));assertEquals(1,available(a));assertEquals(0,jdbc.queryForObject("SELECT action_version FROM book_copy WHERE id=?",Integer.class,a.copy));assertEquals("PREVIEWED",service.get(k,admin).path("state").asText());assertEquals(2,confirm(k,p).path("items").size());}
    @Test void historicUnlimitedUnknownAndNoCopyAndDisabledBorrowerRemainReturnable(){Copy a=copy(),b=copy();List<Long> ids=new ArrayList<>();for(Copy c:List.of(a,b)){jdbc.update("UPDATE book SET stock_available=0 WHERE id=?",c.book);jdbc.update("UPDATE book_copy SET status='BORROWED' WHERE id=?",c.copy);jdbc.update("INSERT INTO borrow_record(user_id,book_id,copy_id,borrow_date,due_date,due_date_kind,status) VALUES (?,?,?,'2020-01-01',NULL,?,'OVERDUE')",member,c.book,c==a?c.copy:null,c==a?"UNLIMITED":"UNKNOWN");ids.add(jdbc.queryForObject("SELECT id FROM borrow_record WHERE book_id=?",Long.class,c.book));}jdbc.update("UPDATE sys_user SET status=0 WHERE id=?",member);String k=UUID.randomUUID().toString();JsonNode r=confirm(k,preview(k,returns(ids.get(0),ids.get(1))));assertEquals("UNLIMITED",r.path("items").get(0).path("dueDateKind").asText());assertTrue(r.path("items").get(1).path("copyId").isNull());for(long id:ids){assertEquals("RETURNED",jdbc.queryForObject("SELECT status FROM borrow_record WHERE id=?",String.class,id));assertNull(jdbc.queryForObject("SELECT due_date FROM borrow_record WHERE id=?",java.sql.Date.class,id));}assertEquals(1,available(a));assertEquals(1,available(b));}
    @Test void roleIsRecheckedAndOwnerCannotBeReplacedEvenByAdministrator(){Copy c=copy();String k=UUID.randomUUID().toString();JsonNode p=preview(k,borrow(c));reason("OWNER_REQUIRED",()->service.confirm(k,obj("previewDigest",p.get("previewDigest")),clerk));jdbc.update("UPDATE sys_user SET role='READER' WHERE id=?",admin);reason("ROLE_REQUIRED",()->service.get(k,admin));reason("ROLE_REQUIRED",()->confirm(k,p));reason("ROLE_REQUIRED",()->service.cancel(k,obj(),admin));jdbc.update("UPDATE sys_user SET role='ADMIN',status=0 WHERE id=?",admin);reason("ROLE_REQUIRED",()->confirm(k,p));assertEquals(1,available(c));}
    @Test void onlyCurrentEnabledUndeletedReadersCanBeNewBorrowTargets(){Copy c=copy();long initialRequests=count("circulation_request"),initialRecords=count("borrow_record"),initialFlows=count("stock_flow");for(long staff:List.of(admin,clerk)){ObjectNode input=borrow(c);input.put("userId",staff);Failure e=assertThrows(Failure.class,()->preview(UUID.randomUUID().toString(),input));assertEquals(404,e.status);assertEquals("MEMBER_NOT_FOUND",e.reason);}jdbc.update("UPDATE sys_user SET status=0 WHERE id=?",member);reason("MEMBER_DISABLED",()->preview(UUID.randomUUID().toString(),borrow(c)));jdbc.update("UPDATE sys_user SET status=1,deleted=1 WHERE id=?",member);reason("MEMBER_NOT_FOUND",()->preview(UUID.randomUUID().toString(),borrow(c)));assertEquals(initialRequests,count("circulation_request"));assertEquals(initialRecords,count("borrow_record"));assertEquals(initialFlows,count("stock_flow"));assertEquals(1,available(c));}
    @Test void borrowerRoleIsFrozenInGuardAndRecheckedAfterPreviewForBothStaffRoles(){Copy c=copy();for(String role:List.of("ADMIN","LIBRARIAN")){jdbc.update("UPDATE sys_user SET role='READER' WHERE id=?",member);String key=UUID.randomUUID().toString();JsonNode p=preview(key,borrow(c));JsonNode guard=read(jdbc.queryForObject("SELECT guard_json FROM circulation_request WHERE operation_key=?",String.class,bytes(key)));assertTrue(java.util.stream.StreamSupport.stream(guard.spliterator(),false).anyMatch(x->"READER".equals(x.path("member").path("role").asText())));jdbc.update("UPDATE sys_user SET role=? WHERE id=?",role,member);reason("PREVIEW_STALE",()->confirm(key,p));assertEquals("PREVIEWED",service.get(key,admin).path("state").asText());assertEquals(1,available(c));}}
    @Test void historicalBorrowerRoleChangeDisabledStatusAndNullNameStillAllowReturn(){Copy a=copy(),b=copy();JsonNode loan=lend(a,b);long first=loan.path("items").get(0).path("recordId").asLong(),second=loan.path("items").get(1).path("recordId").asLong();for(var pair:List.of(Map.entry("ADMIN",first),Map.entry("LIBRARIAN",second))){jdbc.update("UPDATE sys_user SET role=?,status=0,real_name=NULL WHERE id=?",pair.getKey(),member);String key=UUID.randomUUID().toString();JsonNode result=confirm(key,preview(key,returns(pair.getValue())));assertEquals("RETURNED",result.path("items").get(0).path("afterRecordStatus").asText());assertTrue(result.path("items").get(0).path("userName").isNull());}assertEquals(1,available(a));assertEquals(1,available(b));}
    @Test void tenBookLimitAndDuplicateBookApplyTogetherAcrossCurrentLegacyLoans(){Copy[] ten=new Copy[10];for(int i=0;i<10;i++)ten[i]=copy();JsonNode r=lend(ten);assertEquals(10,r.path("items").size());reason("BORROW_LIMIT",()->preview(UUID.randomUUID().toString(),borrow(copy())));long first=r.path("items").get(0).path("recordId").asLong();legacy.returnBook(first);reason("DUPLICATE_BOOK",()->preview(UUID.randomUUID().toString(),borrow(ten[1])));}
    @Test void exactBarcodeAndPositionRemainUnchangedAndStaleRenewalCannotBeSilentlyAccepted(){Copy c=copy();String exact="000 Aa<script>原文</script>"+UUID.randomUUID()+" ";jdbc.update("UPDATE book_copy SET barcode=?,location='原位置' WHERE id=?",exact,c.copy);JsonNode r=lend(c);assertEquals(exact,r.path("items").get(0).path("barcode").asText());String k=UUID.randomUUID().toString();long id=r.path("items").get(0).path("recordId").asLong();JsonNode p=preview(k,returns(id));legacy.renew(id,1);reason("PREVIEW_STALE",()->confirm(k,p));assertEquals("原位置",jdbc.queryForObject("SELECT location FROM book_copy WHERE id=?",String.class,c.copy));}
    @Test void actualLoanDatesUseShanghaiWithUtcJvmDefaultAndKnownNullHistoricalName(){TimeZone original=TimeZone.getDefault();try{TimeZone.setDefault(TimeZone.getTimeZone("UTC"));service.clock=Clock.fixed(Instant.parse("2026-10-20T16:10:00Z"),ZoneOffset.UTC);jdbc.update("UPDATE sys_user SET real_name=NULL WHERE id=?",member);Copy c=copy();JsonNode loan=lend(c);JsonNode row=loan.path("items").get(0);assertEquals("2026-10-21",row.path("borrowDate").asText());assertEquals("2026-11-20",row.path("dueDate").asText());assertTrue(row.path("userName").isNull());assertEquals("2026-10-21",jdbc.queryForObject("SELECT borrow_date FROM borrow_record WHERE id=?",String.class,row.path("recordId").asLong()));String k=UUID.randomUUID().toString();JsonNode returned=confirm(k,preview(k,returns(row.path("recordId").asLong())));assertEquals("2026-10-21",returned.path("items").get(0).path("returnDate").asText());assertEquals("2026-10-21",jdbc.queryForObject("SELECT return_date FROM borrow_record WHERE id=?",String.class,row.path("recordId").asLong()));}finally{TimeZone.setDefault(original);}}
    @Test void fundsPlansEntitlementsAndMemberProfileRemainByteIdentical()throws Exception{Set<String> protectedTables=new TreeSet<>();Map<String,List<String>> before;try(Connection c=Objects.requireNonNull(jdbc.getDataSource()).getConnection();ResultSet r=c.getMetaData().getTables(null,null,"%",new String[]{"TABLE"})){while(r.next()){String t=r.getString("TABLE_NAME"),n=t.toLowerCase(Locale.ROOT);if(n.startsWith("member_finance")||n.startsWith("member_entitlement")||n.startsWith("membership_plan")||n.equals("member_profile"))protectedTables.add(t);}before=CirculationMigrationTest.rows(c,protectedTables);}assertTrue(protectedTables.size()>=7);Copy a=copy(),b=copy();JsonNode receipt=lend(a,b);String ret=UUID.randomUUID().toString();confirm(ret,preview(ret,returns(receipt.path("items").get(0).path("recordId").asLong(),receipt.path("items").get(1).path("recordId").asLong())));service.cancel(UUID.randomUUID().toString(),obj(),admin);try(Connection c=Objects.requireNonNull(jdbc.getDataSource()).getConnection()){assertEquals(before,CirculationMigrationTest.rows(c,protectedTables));}}
    @Test void sameKeyAndOverlappingReturnsAreSerializedAndNoStockOrFlowIsDuplicated()throws Exception{Copy a=copy(),b=copy();String k=UUID.randomUUID().toString();JsonNode p=preview(k,borrow(a,b));List<Object> replies=parallel(()->confirm(k,p),()->confirm(k,p));assertInstanceOf(JsonNode.class,replies.get(0));assertEquals(replies.get(0),replies.get(1));long record=((JsonNode)replies.get(0)).path("items").get(0).path("recordId").asLong();String x=UUID.randomUUID().toString(),y=UUID.randomUUID().toString();JsonNode xp=preview(x,returns(record)),yp=preview(y,returns(record));List<Object> returns=parallel(()->confirm(x,xp),()->confirm(y,yp));assertEquals(1,returns.stream().filter(JsonNode.class::isInstance).count());assertEquals(1,available(a));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM stock_flow WHERE related_id=? AND flow_type='RETURN'",Integer.class,record));}
    @Test void oppositeInputOrderAndLegacyBorrowCompetitionNeverDeadlockOrExceedLimit()throws Exception{Copy a=copy(),b=copy();String x=UUID.randomUUID().toString(),y=UUID.randomUUID().toString();JsonNode xp=preview(x,borrow(a,b)),yp=preview(y,borrow(b,a));List<Object> both=parallel(()->confirm(x,xp),()->confirm(y,yp));assertEquals(1,both.stream().filter(JsonNode.class::isInstance).count());Copy c=copy();String k=UUID.randomUUID().toString();JsonNode p=preview(k,borrow(c));BorrowRequest old=new BorrowRequest();old.setUserId(user("READER"));old.setBookId(c.book);old.setCopyId(c.copy);List<Object> race=parallel(()->confirm(k,p),()->legacy.borrow(old));assertEquals(1,race.stream().filter(v->v instanceof JsonNode||v instanceof BorrowRecord).count());assertEquals(0,available(c));}
    @Test void cancelVersusPreviewAndConfirmAlwaysHasOneDurableTerminalOutcome()throws Exception{String k=UUID.randomUUID().toString();Copy c=copy();parallel(()->preview(k,borrow(c)),()->service.cancel(k,obj(),admin));assertEquals("CANCELLED",service.get(k,admin).path("state").asText());assertEquals(1,available(c));String x=UUID.randomUUID().toString();JsonNode p=preview(x,borrow(c));parallel(()->confirm(x,p),()->service.cancel(x,obj(),admin));JsonNode r=service.get(x,admin);assertTrue(Set.of("COMMITTED","CANCELLED").contains(r.path("state").asText()));assertEquals(r.path("state").asText().equals("COMMITTED")?0:1,available(c));}
    @SafeVarargs final List<Object> parallel(Callable<Object>... calls)throws Exception{ExecutorService pool=Executors.newFixedThreadPool(calls.length);CountDownLatch ready=new CountDownLatch(calls.length),start=new CountDownLatch(1);List<Future<Object>> futures=new ArrayList<>();try{for(var call:calls)futures.add(pool.submit(()->{ready.countDown();start.await();try{return call.call();}catch(Failure e){return e;}catch(DataAccessException e){throw e;}catch(RuntimeException e){return e;}}));assertTrue(ready.await(5,TimeUnit.SECONDS));start.countDown();List<Object> result=new ArrayList<>();for(var f:futures)result.add(f.get(30,TimeUnit.SECONDS));for(Object o:result)if(o instanceof Failure f)assertNotEquals("CIRCULATION_BUSY",f.reason,"Unexpected deadlock or timeout");return result;}finally{start.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}
}
